#!/usr/bin/env node
/* eslint-env node */
/* eslint-disable no-console */
// Regenerates src/tracker-bundle.ts from packages/tracker/dist/tracker.js.
//
// The worker serves the tracker itself (/v1/tracker.js and
// /v1/tracker.{version}.js): the dashboard sits behind Cloudflare Access, so
// there is no public host to fetch it from, and serving it from the host that
// served the document keeps it first-party.
//
// The version is the first 12 hex characters of the bundle's SHA-256, so new
// bytes are a new address and no cache anywhere holds a stale copy at it.
//
// Run by wrangler's build command (wrangler.jsonc) after the tracker build,
// so every deploy and every `wrangler dev` ships the bytes it hashes. The
// generated file is committed too, so typecheck and tests work without a build;
// tests/tracker-bundle.test.ts fails when it has drifted from a fresh build.
import { createHash } from 'node:crypto';
import { existsSync, readFileSync, writeFileSync } from 'node:fs';
import { pathToFileURL } from 'node:url';

export const TRACKER_FILE = new URL('../../tracker/dist/tracker.js', import.meta.url);
export const BUNDLE_FILE = new URL('../src/tracker-bundle.ts', import.meta.url);

/** The version segment: the first 12 hex characters of the bundle's SHA-256. */
export const trackerVersion = (bytes) =>
  createHash('sha256').update(bytes).digest('hex').slice(0, 12);

/** The served bytes: the build output without its sourceMappingURL comment (the map is not served). */
export const servedSource = (raw) => raw.replace(/\n?\/\/# sourceMappingURL=.*\s*$/, '\n');

export const bundleModule = (source) =>
  [
    '// GENERATED by scripts/tracker-bundle.mjs from packages/tracker/dist/tracker.js.',
    '// Do not edit by hand; run `pnpm --filter @htmlradar/proxy tracker`.',
    '/* eslint-disable */',
    `export const TRACKER_VERSION = '${trackerVersion(source)}';`,
    `export const TRACKER_JS = ${JSON.stringify(source)};`,
    '',
  ].join('\n');

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  const source = servedSource(readFileSync(TRACKER_FILE, 'utf8'));
  const next = bundleModule(source);
  // Unchanged bytes are not rewritten, so a file watcher sees no change.
  if (!existsSync(BUNDLE_FILE) || readFileSync(BUNDLE_FILE, 'utf8') !== next) {
    writeFileSync(BUNDLE_FILE, next);
  }
  console.log(`tracker ${trackerVersion(source)} (${source.length} bytes)`);
}
